def strategy(history, rng):
    n = len(history)

    if n == 0:
        return 'C'

    # In the final round there is no future to protect, so exploit.
    if n == 99:
        return 'D'

    opp_d = 0
    my_d = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0

    for a, b in history:
        if a == 'C':
            if b == 'C':
                cc += 1
            else:
                cd += 1
        else:
            my_d += 1
            if b == 'C':
                dc += 1
            else:
                dd += 1
        if b == 'D':
            opp_d += 1

    last_my, last_opp = history[-1]

    recent3 = history[-3:]
    recent5 = history[-5:]
    recent10 = history[-10:]

    r3_od = sum(1 for a, b in recent3 if b == 'D')
    r5_od = sum(1 for a, b in recent5 if b == 'D')
    r10_od = sum(1 for a, b in recent10 if b == 'D')

    opp_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_d_streak += 1
        i -= 1

    my_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D':
        my_d_streak += 1
        i -= 1

    # Infer whether the opponent punishes our unilateral defection.
    tolerated = 0
    punished = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            if history[i + 1][1] == 'C':
                tolerated += 1
            elif history[i + 1][1] == 'D':
                punished += 1

    remaining = 100 - n

    low_defect = (opp_d * 10 <= n) and (opp_d <= max(3, n // 20))
    exploited = cd > dc + 1
    cooperative_partner = low_defect and not exploited

    # Opponent has never defected: after a short cooperative probe,
    # exploit a confirmed non-punishing cooperator.
    if opp_d == 0:
        if n < 20:
            return 'C'
        if tolerated >= 1:
            return 'D'
        if last_my == 'D':
            # Give one observation round before deciding this is exploitable.
            return 'C'
        if last_my == 'C' and last_opp == 'C':
            return 'D'
        return 'C'

    # If the opponent has repeatedly tolerated our defections, defect.
    # If they ever begin to punish, this condition stops and we retaliate.
    if n >= 30 and punished == 0 and tolerated >= 3:
        return 'D'

    # Strongly defective opponents: mostly defect, but do not punish
    # a cooperative response if it might open a mutually cooperative gap.
    if opp_d * 3 >= n * 2:
        if last_opp == 'C':
            if last_my == 'C' and cd > dc + 2:
                return 'D'
            return 'C'
        return 'D'

    # Opponent defected last round.
    if last_opp == 'D':
        # Repeated recent defections: do not be taken advantage of.
        if r3_od >= 2:
            return 'D'

        # Opponent exploited our cooperation.
        if last_my == 'C':
            # If they were otherwise very cooperative and this was isolated,
            # offer a one-round chance to return to cooperation.
            if cooperative_partner and r5_od <= 1 and cc * 2 >= n:
                return 'C'
            return 'D'

        # Mutual defection. Try to break short punishment spirals.
        if cooperative_partner:
            return 'C'

        if opp_d_streak >= 3 and my_d_streak >= 3:
            # If they are not overwhelmingly defective, use a conciliatory move.
            if opp_d * 3 < n * 2:
                return 'C'
            return 'D'

        # After limited recent conflict, repair if mutual cooperation is still
        # a good bet.
        if r10_od <= 3 and cc * 3 >= n * 2:
            return 'C'

        return 'D'

    # Opponent cooperated last round.
    # If we just defected and they did not punish, the broad tolerant-exploit
    # rule above would normally have caught it; otherwise return to cooperation.
    if last_my == 'D':
        return 'C'

    # Mutual cooperation.
    # In the very endgame, avoid being punished by reactive strategies before
    # the final round, except against clearly non-cooperative opponents.
    if remaining <= 3:
        if opp_d * 3 >= n:
            return 'D'
        return 'C'

    # Mixed opponents: add a small controlled defect probability proportional
    # to their observed aggression.
    if opp_d * 5 > n:
        if rng.random() < (opp_d / float(n)) * 0.65:
            return 'D'

    return 'C'
